template <int idx>
static __fi int _vifCode_STColRow(const u32* data, u32* pmem2)
{
	vifStruct& vifX = GetVifX;

	const int ret = std::min(4 - vifX.tag.addr, vifX.vifpacketsize);
	pxAssume(vifX.tag.addr < 4);
	pxAssume(ret > 0);

	switch (ret)
	{
		case 4:
			pmem2[3] = data[3];
			[[fallthrough]];
		case 3:
			pmem2[2] = data[2];
			[[fallthrough]];
		case 2:
			pmem2[1] = data[1];
			[[fallthrough]];
		case 1:
			pmem2[0] = data[0];
			break;
			jNO_DEFAULT
	}

	vifX.tag.addr += ret;
	vifX.tag.size -= ret;
	if (!vifX.tag.size)
	{
		vifX.pass = 0;
		vifX.cmd = 0;
	}



	return ret;
}

